-- =============================================================
-- mybatis-plus-demo 初始化脚本 —— GaussDB / openGauss（PG 族）口径
-- 目标实例：GaussDB Kernel 503.1.0（103.36.220.245:25882 / xc3_test，兼容模式 A）
-- 与 schema.sql 的差异（逐条对应，改回 MySQL 时别照抄本文件）：
--   1. 反引号 → 去掉；"user" 是 PG 族保留字，必须带双引号（连 DROP/SELECT 一起带）
--   2. AUTO_INCREMENT → SERIAL（该实例不支持 GENERATED BY DEFAULT AS IDENTITY，
--      实测报 syntax error at or near "by"），种子数据之后用 setval 把序列顶到 max(id)
--   3. DATETIME → TIMESTAMP；TINYINT → SMALLINT
--   4. 内联 KEY 索引 → 独立 CREATE INDEX；ENGINE / CHARSET / 表级 COMMENT 子句去掉，
--      表注释改 COMMENT ON TABLE
--   5. 去掉 USE mp_demo（连接串已指定 xc3_test）
--   6. 可重复执行：每张表先 DROP IF EXISTS
-- =============================================================

DROP TABLE IF EXISTS t_order;
DROP TABLE IF EXISTS "user";
DROP TABLE IF EXISTS department;
DROP TABLE IF EXISTS role;
DROP TABLE IF EXISTS sys_config;
DROP TABLE IF EXISTS user_role;
DROP TABLE IF EXISTS wkfl_proc;
DROP TABLE IF EXISTS wkfl_task;
DROP TABLE IF EXISTS wkfl_solicit;
DROP TABLE IF EXISTS core_apply_duties;
DROP TABLE IF EXISTS t_mixed_profile;

-- 用户表
CREATE TABLE "user" (
    id          SERIAL       NOT NULL,
    username    VARCHAR(64)  NOT NULL,
    password    VARCHAR(128) DEFAULT NULL,
    age         INT          DEFAULT NULL,
    email       VARCHAR(128) DEFAULT NULL,
    role_id     INT          DEFAULT NULL,
    dept_id     INT          DEFAULT NULL,
    status      SMALLINT     DEFAULT 1,
    remark      VARCHAR(255) DEFAULT NULL,
    create_time TIMESTAMP    DEFAULT NULL,
    update_time TIMESTAMP    DEFAULT NULL,
    deleted     SMALLINT     DEFAULT 0,
    version     INT          DEFAULT 0,
    PRIMARY KEY (id)
);
CREATE INDEX idx_username ON "user" (username);
CREATE INDEX idx_role_id ON "user" (role_id);
CREATE INDEX idx_dept_id ON "user" (dept_id);
COMMENT ON TABLE "user" IS '用户表（表名为 PG 族保留字，必须带双引号引用）';

-- 角色表
CREATE TABLE role (
    id          SERIAL      NOT NULL,
    name        VARCHAR(64) NOT NULL,
    code        VARCHAR(32) DEFAULT NULL,
    description VARCHAR(255) DEFAULT NULL,
    PRIMARY KEY (id)
);
COMMENT ON TABLE role IS '角色表';

-- 部门表
CREATE TABLE department (
    id        SERIAL      NOT NULL,
    name      VARCHAR(64) NOT NULL,
    code      VARCHAR(32) DEFAULT NULL,
    parent_id INT         DEFAULT NULL,
    sort      INT         DEFAULT 0,
    PRIMARY KEY (id)
);
COMMENT ON TABLE department IS '部门表';

-- 订单表
CREATE TABLE t_order (
    id          SERIAL        NOT NULL,
    order_no    VARCHAR(64)   NOT NULL,
    user_id     INT           DEFAULT NULL,
    amount      DECIMAL(10, 2) DEFAULT NULL,
    status      SMALLINT      DEFAULT 0,
    create_time TIMESTAMP     DEFAULT NULL,
    PRIMARY KEY (id)
);
CREATE INDEX idx_user_id ON t_order (user_id);
COMMENT ON TABLE t_order IS '订单表';

-- 系统配置表
CREATE TABLE sys_config (
    id           SERIAL       NOT NULL,
    config_key   VARCHAR(128) NOT NULL,
    config_value VARCHAR(255) DEFAULT NULL,
    config_type  INT          DEFAULT NULL,
    remark       VARCHAR(255) DEFAULT NULL,
    sort_no      INT          DEFAULT 0,
    PRIMARY KEY (id)
);
COMMENT ON TABLE sys_config IS '系统配置表';

-- 用户角色关系表
CREATE TABLE user_role (
    id      SERIAL NOT NULL,
    user_id INT DEFAULT NULL,
    role_id INT DEFAULT NULL,
    PRIMARY KEY (id)
);
CREATE INDEX idx_ur_user_id ON user_role (user_id);
COMMENT ON TABLE user_role IS '用户角色关系表';

-- 工作流演示表（StringSqlDaoDemoServiceImpl 自研框架字符串 SQL 场景）
CREATE TABLE wkfl_proc (
    proc_id      VARCHAR(64) NOT NULL,
    proc_name    VARCHAR(128) DEFAULT NULL,
    proc_def_key VARCHAR(128) DEFAULT NULL,
    object_id    VARCHAR(64) DEFAULT NULL,
    PRIMARY KEY (proc_id)
);
CREATE INDEX idx_proc_def_key ON wkfl_proc (proc_def_key);
COMMENT ON TABLE wkfl_proc IS '工作流流程定义表';

CREATE TABLE wkfl_task (
    task_id     VARCHAR(64) NOT NULL,
    proc_id     VARCHAR(64) DEFAULT NULL,
    owner       VARCHAR(64) DEFAULT NULL,
    finish_type VARCHAR(32) DEFAULT NULL,
    PRIMARY KEY (task_id)
);
CREATE INDEX idx_task_proc_id ON wkfl_task (proc_id);
CREATE INDEX idx_task_owner ON wkfl_task (owner);
COMMENT ON TABLE wkfl_task IS '工作流任务表';

CREATE TABLE wkfl_solicit (
    solicit_id VARCHAR(64) NOT NULL,
    proc_id    VARCHAR(64) DEFAULT NULL,
    PRIMARY KEY (solicit_id)
);
CREATE INDEX idx_solicit_proc_id ON wkfl_solicit (proc_id);
COMMENT ON TABLE wkfl_solicit IS '工作流征询表';

CREATE TABLE core_apply_duties (
    apply_id    VARCHAR(64) NOT NULL,
    policy_name VARCHAR(128) DEFAULT NULL,
    PRIMARY KEY (apply_id)
);
COMMENT ON TABLE core_apply_duties IS '担保函申请业务表';

-- 混合注解实体（T-Embedded G3 语料）
CREATE TABLE t_mixed_profile (
    id           SERIAL       NOT NULL,
    name         VARCHAR(64)  DEFAULT NULL,
    theme        VARCHAR(32)  DEFAULT NULL,
    notify_email VARCHAR(128) DEFAULT NULL,
    max_retry    INT          DEFAULT NULL,
    remark       VARCHAR(255) DEFAULT NULL,
    PRIMARY KEY (id)
);
COMMENT ON TABLE t_mixed_profile IS '混合注解实体（静态预览语料）';

