-- 种子数据带显式 id 插入，SERIAL 序列不会自动前进 —— 顶到 max(id)，避免应用侧 AUTO 主键冲突
SELECT setval('role_id_seq', (SELECT max(id) FROM role));
SELECT setval('department_id_seq', (SELECT max(id) FROM department));
SELECT setval('user_id_seq', (SELECT max(id) FROM "user"));
SELECT setval('t_order_id_seq', (SELECT max(id) FROM t_order));
SELECT setval('sys_config_id_seq', (SELECT max(id) FROM sys_config));
SELECT setval('user_role_id_seq', (SELECT max(id) FROM user_role));
